427:     function drawSlantedText(text, x, y, size, topCol, botCol, strokeWidth = 10) {
428:       ctx.save();
429:       ctx.translate(x, y);
430:       ctx.transform(1, 0, -0.15, 1, 0, 0);
431:       ctx.font = `900 ${size}px 'Black Han Sans', 'Noto Sans KR', sans-serif`;
432:       ctx.lineJoin = "round";
433:       ctx.shadowColor = "rgba(0,0,0,0.82)";
434:       ctx.shadowBlur = 10;
435:       ctx.shadowOffsetX = 4;
436:       ctx.shadowOffsetY = 6;
437:       ctx.lineWidth = strokeWidth;
438:       ctx.strokeStyle = "#000000";
439:       ctx.strokeText(text, 0, 0);
440: 
441:       ctx.shadowColor = "transparent";
442:       const grad = ctx.createLinearGradient(0, -size * 0.85, 0, 10);
443:       grad.addColorStop(0, topCol);
444:       grad.addColorStop(1, botCol);
445:       ctx.fillStyle = grad;
446:       ctx.fillText(text, 0, 0);
447:       ctx.restore();
448:     }
